using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class CalculateLoyaltyDiscountAcceptanceTests
{
    private readonly CalculateLoyaltyDiscount _useCase = new();

    // Bronze customer is charged 9500 cents for a 10000 cent basket
    [Fact]
    public void S1_BronzeBasketOf10000CentsIsCharged9500Cents()
    {
        var quote = _useCase.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }

    // Silver customer is charged 9000 cents for a 10000 cent basket
    [Fact]
    public void S2_SilverBasketOf10000CentsIsCharged9000Cents()
    {
        var quote = _useCase.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Silver));

        Assert.Equal(9000, quote.TotalCents);
    }

    // Gold customer is charged 8500 cents for a 10000 cent basket
    [Fact]
    public void S3_GoldBasketOf10000CentsIsCharged8500Cents()
    {
        var quote = _useCase.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Gold));

        Assert.Equal(8500, quote.TotalCents);
    }

    // Bronze customer's reduction lands on a whole cent in the customer's favour
    [Fact]
    public void S4_BronzeBasketOf7CentsIsCharged7Cents()
    {
        var quote = _useCase.Handle(new CalculateLoyaltyDiscountQuery(7, LoyaltyTier.Bronze));

        Assert.Equal(7, quote.TotalCents);
    }
}

